use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::process;

/// Running state of one key: either the sum so far, or a marker that a
/// running total left the signed 64-bit range at some point.
enum Total {
    Sum(i64),
    Overflow,
}

fn main() {
    if let Err(err) = run() {
        eprintln!("keyed-totals: {err}");
        process::exit(1);
    }
}

fn run() -> Result<(), Box<dyn Error>> {
    let path = env::args_os()
        .nth(1)
        .ok_or("usage: keyed-totals <file>")?;
    let bytes = fs::read(&path)
        .map_err(|e| format!("cannot read {}: {e}", path.to_string_lossy()))?;
    let text = String::from_utf8(bytes).map_err(|_| "input is not valid UTF-8")?;

    let mut lines = text.lines();

    // First section: records, up to the first empty line.
    let mut totals: HashMap<&str, Total> = HashMap::new();
    for line in lines.by_ref() {
        if line.is_empty() {
            break;
        }
        let (key, value) = line
            .split_once(' ')
            .ok_or_else(|| format!("malformed record: {line:?}"))?;
        let value: i64 = value
            .trim()
            .parse()
            .map_err(|_| format!("malformed value in record: {line:?}"))?;

        let entry = totals.entry(key).or_insert(Total::Sum(0));
        if let Total::Sum(sum) = *entry {
            *entry = match sum.checked_add(value) {
                Some(next) => Total::Sum(next),
                None => Total::Overflow,
            };
        }
    }

    // Second section: queries, one key per line, answered in order.
    let mut out = BufWriter::new(io::stdout().lock());
    for line in lines {
        let key = line.trim();
        if key.is_empty() {
            continue;
        }
        match totals.get(key) {
            None => writeln!(out, "{key}=absent")?,
            Some(Total::Sum(total)) => writeln!(out, "{key}={total}")?,
            Some(Total::Overflow) => writeln!(out, "{key}=overflow")?,
        }
    }
    out.flush()?;
    Ok(())
}

